    14	    /**
    15	     * @brief The flat tables of a Sobol RQMC run of `replicates` replicates:
    16	     *        the generic engine's scheme -- replicate b is
    17	     *        SobolSequence(dim, (seed << 32) | b) -- and, when `bridge` is
    18	     *        set and the model describes its increments, its Brownian bridge
    19	     *        (BridgedGaussians' own tables).
    20	     */
    21	    inline SobolTables sobol_tables(std::size_t dimension, uint64_t seed, int replicates,
    22	                                    const BrownianLayout &layout, bool bridge, bool owen = false)
    23	    {
    24	        SobolTables t;
    25	        t.dim = static_cast<int>(dimension);
    26	        t.owen = owen;
    27	        t.replicates = replicates;
    28	        for (int b = 0; b < replicates; ++b)
    29	        {
    30	            const uint64_t batch_seed =
    31	                (static_cast<uint64_t>(static_cast<uint32_t>(seed)) << 32) | static_cast<uint64_t>(b);
    32	            const SobolSequence s(t.dim, batch_seed);
    33	            if (b == 0)
    34	                t.V.assign(s.directions().begin(), s.directions().end());
    35	            t.shift.insert(t.shift.end(), s.shifts().begin(), s.shifts().end());
    36	        }
    37	        if (bridge && layout.covers(dimension))
    38	        {
    39	            const BridgedGaussians g(layout.times, layout.factors, layout.stride);
    40	            const BrownianBridge &br = g.bridge();
    41	            t.bridge_index = br.bridge_index();
    42	            t.left_index = br.left_index();
    43	            t.right_index = br.right_index();
    44	            t.left_weight = br.left_weight();
    45	            t.right_weight = br.right_weight();
    46	            t.std_dev = br.std_dev();
    47	            t.inv_sqrt_dt = g.inv_sqrt_dt();
    48	            t.n = static_cast<int>(layout.times.size());
    49	            t.factors = static_cast<int>(layout.factors);
    50	            t.stride = static_cast<int>(layout.stride);
    51	        }
    52	        return t;
    53	    }
